/**
 * @description Plays Fruit Ninja with one short predictive slash per stream-tracked fruit instead of chasing stale screenshot detections.
 * @window Fruit Ninja Benchmark — Google Chrome
 * @useWhen Chrome is showing Fruit Ninja and a human-like, visually precise alternative to fruitNinjaFull is desired.
 * @startState The Fruit Ninja tab is focused at the start screen, during a round, or on the completed results screen.
 * @endState The Game Over results remain visible. Play Again is never clicked.
 * @notes Uses sdk.trackObjects over a persistent 60 FPS stream. Stable track IDs guarantee at most one slash per tracked fruit; rising fruit are intercepted near their predicted apex and uncertain/descending fruit use a short latency-compensated intercept. Each slash is limited to roughly one fruit diameter.
 */
import { sdk } from '@tyvm/knowhow-module-computer-use';

const requiredWindow = { app: 'Google Chrome', titleIncludes: 'Fruit Ninja Benchmark' };
const slashedTrackIds = new Set();
let slashCount = 0;
let sawFruit = false;
let lastFruitAt = sdk.elapsed();
let lastLifecycleAt = -10000;
let tracker;

async function lifecyclePhase() {
  const elements = await sdk.accessibilityElements({ interactiveOnly: true });
  const button = elements.find((element) => {
    const text = `${element.title || ''} ${element.value || ''}`;
    return element.role === 'AXButton' && /Start Game|Play Again/i.test(text);
  });
  if (!button) return { phase: 'playing' };
  const text = `${button.title || ''} ${button.value || ''}`;
  return /Play Again/i.test(text) ? { phase: 'end' } : { phase: 'start', button };
}

async function handleLifecycle() {
  lastLifecycleAt = sdk.elapsed();
  const lifecycle = await lifecyclePhase();
  if (lifecycle.phase === 'end') {
    sdk.log({ phase: 'end', slashCount, action: 'stop-with-results-visible' });
    sdk.ctl.stop();
    return false;
  }
  if (lifecycle.phase === 'start' && lifecycle.button?.bounds) {
    const bounds = lifecycle.button.bounds;
    await sdk.clickAt(bounds.x + bounds.width / 2, bounds.y + bounds.height / 2);
    sdk.log({ phase: 'start', action: 'click-start-game' });
    await sdk.sleep(150);
  }
  lastFruitAt = sdk.elapsed();
  return true;
}

async function resolveArena(windowBounds) {
  const elements = await sdk.accessibilityElements({ interactiveOnly: false });
  const canvases = elements
    .filter((element) => element.role === 'AXCanvas' && element.bounds)
    .sort((a, b) => (b.bounds.width * b.bounds.height) - (a.bounds.width * a.bounds.height));
  if (canvases[0]) return canvases[0].bounds;

  const webAreas = elements
    .filter((element) => element.role === 'AXWebArea' && element.bounds)
    .sort((a, b) => (b.bounds.width * b.bounds.height) - (a.bounds.width * a.bounds.height));
  const page = webAreas[0]?.bounds || windowBounds;
  return {
    x: page.x,
    y: page.y + page.height * 0.06,
    width: page.width,
    height: page.height * 0.94,
  };
}

let active = await sdk.activeWindow();
while (!sdk.ctl.stopped && (active?.app !== requiredWindow.app
  || !active?.title?.includes(requiredWindow.titleIncludes))) {
  await sdk.sleep(50);
  active = await sdk.activeWindow();
}
if (!active?.bounds) throw new Error('The focused Fruit Ninja window has no usable bounds.');

if (await handleLifecycle()) {
  const arena = await resolveArena(active.bounds);
  const expectedDiameter = arena.width * (70 / 1200);
  tracker = await sdk.trackObjects({
    region: arena,
    scale: 0.25,
    fps: 60,
    framesToKeep: 3,
    mode: 'foreground',
    minSize: Math.max(24, expectedDiameter * 0.55),
    maxSize: expectedDiameter * 1.45,
    minPixels: Math.max(250, expectedDiameter * expectedDiameter * 0.08),
    clusterGap: 4,
    dilate: 0,
    maxBoxes: 40,
    maxAssociationDistance: expectedDiameter * 2.2,
    historySize: 12,
    maxMissedFrames: 4,
    smoothing: 0.4,
    filter: (blob) => {
      const { width, height } = blob.bounds;
      const aspect = width / height;
      return aspect >= 0.72 && aspect <= 1.28
        && width >= expectedDiameter * 0.58 && width <= expectedDiameter * 1.45
        && height >= expectedDiameter * 0.58 && height <= expectedDiameter * 1.45;
    },
  });
  sdk.log({ phase: 'ready', perception: 'stream-tracker', arena, expectedDiameter,
    scale: 0.25, requestedFps: 60 });

  async function tick() {
    const observation = await tracker.nextFrame(250);
    const now = sdk.elapsed();
    if (!observation) {
      if (sawFruit && now - lastFruitAt > 4500 && now - lastLifecycleAt > 4500) {
        await handleLifecycle();
      }
      return;
    }
    const fruits = observation.objects.filter((object) => object.missedFrames === 0);
    if (fruits.length) {
      sawFruit = true;
      lastFruitAt = now;
    }

    for (const fruit of fruits) {
      if (slashedTrackIds.has(fruit.id) || fruit.ageFrames < 4) continue;

      // Wait for a trustworthy ballistic apex while the fruit is rising. If
      // acceleration has not stabilized after several frames, do not risk
      // waiting too long: intercept its latency-compensated future position.
      const speed = Math.hypot(fruit.velocity.x, fruit.velocity.y);
      const apexIsPlausible = fruit.apex
        && speed >= 120
        && fruit.velocity.y < -50
        && fruit.acceleration.y >= 300
        && fruit.acceleration.y <= 4000
        && fruit.apex.timeUntilMs > 0
        && fruit.apex.timeUntilMs < 1600
        && fruit.apex.point.x >= arena.x
        && fruit.apex.point.x <= arena.x + arena.width
        && fruit.apex.point.y >= arena.y
        && fruit.apex.point.y <= arena.y + arena.height;

      let target;
      let strategy;
      if (apexIsPlausible) {
        if (fruit.apex.timeUntilMs > 70) continue;
        target = fruit.apex.point;
        strategy = 'predicted-apex';
      } else if (speed >= 120 && (fruit.velocity.y >= -30 || fruit.ageFrames >= 10)) {
        target = fruit.predict(45);
        strategy = '45ms-intercept';
      } else {
        continue;
      }

      target = {
        x: Math.max(arena.x, Math.min(arena.x + arena.width, target.x)),
        y: Math.max(arena.y, Math.min(arena.y + arena.height, target.y)),
      };
      const radius = Math.max(fruit.bounds.width, fruit.bounds.height) / 2;
      const halfSlash = Math.min(expectedDiameter * 0.72, radius * 0.85);
      const x1 = Math.max(arena.x, target.x - halfSlash);
      const y1 = Math.min(arena.y + arena.height, target.y + halfSlash * 0.35);
      const x2 = Math.min(arena.x + arena.width, target.x + halfSlash);
      const y2 = Math.max(arena.y, target.y - halfSlash * 0.35);

      // Retire the stable object ID before awaiting input so no later frame can
      // schedule a second slash for the same moving fruit.
      slashedTrackIds.add(fruit.id);
      sdk.log({ phase: 'playing', trackId: fruit.id, strategy,
        ageFrames: fruit.ageFrames, confidence: +fruit.confidence.toFixed(2),
        observed: fruit.center, target,
        velocity: fruit.velocity, acceleration: fruit.acceleration,
        apexInMs: fruit.apex ? Math.round(fruit.apex.timeUntilMs) : null,
        detectionMs: observation.detectionMs, slash: { x1, y1, x2, y2 } });
      await sdk.dragMouse(x1, y1, x2, y2, { duration: 28 });
      slashCount++;
    }

    if (sawFruit && now - lastFruitAt > 4500 && now - lastLifecycleAt > 4500) {
      await handleLifecycle();
    }
  }

  await sdk.runEvery(tick, 20, { requiredWindow });
}

